<style>
.dl-article-page{background:#fcfbf7;padding-bottom:64px}.dl-article-breadcrumb{display:flex;flex-wrap:wrap;gap:10px;padding:25px 0;font-size:12px;line-height:1.7;color:#697462}.dl-article-breadcrumb a{color:inherit;text-decoration:none}.dl-article-breadcrumb [aria-current]{color:var(--dl-forest);overflow-wrap:anywhere}
.dl-article-heading{max-width:920px;margin:24px auto 36px;text-align:center}.dl-article-kicker{color:var(--dl-olive);font-size:11px;line-height:1.7;font-weight:700;letter-spacing:1.8px;text-transform:uppercase;margin:0 0 16px}.dl-article-category{display:inline-block;border:1px solid #d5decc;background:#edf1e6;padding:7px 14px;border-radius:30px;font-size:11px;color:var(--dl-olive)}.dl-article-heading h1{font-size:clamp(30px,3.5vw,49px);letter-spacing:-1.3px;line-height:1.25;color:var(--dl-forest);margin:20px 0;overflow-wrap:anywhere}.dl-article-intro{max-width:760px;margin:0 auto;color:#5c6856;font-size:16px;line-height:1.9}.dl-article-meta{display:flex;justify-content:center;align-items:center;flex-wrap:wrap;gap:22px;margin-top:25px;font-size:12px;color:#6b7564}.dl-article-meta time,.dl-article-meta>span{display:flex;gap:9px;align-items:center}.dl-article-meta a{color:var(--dl-olive);font-weight:600;text-decoration:none}.dl-article-meta a span{margin-left:10px}
.dl-article-cover{margin:0;overflow:hidden;border-radius:18px;background:var(--dl-cream);aspect-ratio:2.15}.dl-article-cover img{width:100%;height:100%;object-fit:cover;display:block}.dl-article-layout{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:64px;padding-top:48px}.dl-article-main{min-width:0}.dl-article-content{font-size:16px;line-height:1.95;color:#455340;scroll-margin-top:28px}.dl-article-content h2,.dl-article-content h3{color:var(--dl-forest);line-height:1.4;letter-spacing:-.4px;scroll-margin-top:28px}.dl-article-content h2{font-size:27px;margin:38px 0 18px}.dl-article-content h3{font-size:22px;margin:30px 0 16px}.dl-article-content>:first-child{margin-top:0}.dl-article-content p{margin:0 0 22px}.dl-article-content blockquote{margin:28px 0;border-left:3px solid var(--dl-amber);padding:22px 26px;background:var(--dl-cream);border-radius:0 10px 10px 0;font-size:18px;color:var(--dl-forest)}.dl-article-content blockquote>:last-child{margin-bottom:0}.dl-article-content img{border-radius:12px}.dl-article-content table{display:block;overflow-x:auto;width:100%}.dl-article-content li{margin-bottom:8px}.dl-article-content a{text-underline-offset:4px}.dl-article-content pre{overflow-x:auto;max-width:100%;padding:16px;background:#edf1e6}.dl-article-content iframe{width:100%}
.dl-article-sidebar{align-self:start;position:sticky;top:24px;display:grid;gap:24px}.dl-article-toc{padding:26px;border:1px solid #dce2d4;border-radius:14px;background:#fff}.dl-article-toc[hidden]{display:none}.dl-article-toc h2{font-size:20px;color:var(--dl-forest);margin:0 0 20px}.dl-article-toc ol{margin:0;padding-left:20px;max-height:340px;overflow-y:auto}.dl-article-toc li{padding:8px 0 8px 3px;font-size:13px;line-height:1.7;color:var(--dl-olive)}.dl-article-toc a{color:#5b6852;text-decoration:none;overflow-wrap:anywhere}.dl-article-toc a:hover,.dl-article-toc a[aria-current]{color:var(--dl-forest);text-decoration:underline;text-underline-offset:4px}.dl-article-toc .dl-article-toc-sub{margin-left:12px;font-size:12px}
.dl-article-advice{background:var(--dl-forest);color:#d3dfcd;border-radius:14px;padding:28px}.dl-article-advice>i{font-size:32px;color:#e8bd70;margin-bottom:24px}.dl-article-advice .dl-article-kicker{color:#e8bd70;font-size:10px}.dl-article-advice h2{color:#fff;font-size:25px;letter-spacing:-.5px;line-height:1.35;margin:0 0 16px}.dl-article-advice>p:not(.dl-article-kicker){font-size:13px;line-height:1.85}.dl-article-advice .dl-primary{font-size:12px;padding:15px 12px;display:flex;justify-content:space-between;margin-top:24px}
.dl-article-tags{display:flex;gap:10px;flex-wrap:wrap;margin-top:32px}.dl-article-tags a{font-size:12px;color:var(--dl-olive);text-decoration:none;background:#eaf0e2;padding:9px 13px;border-radius:6px}.dl-article-end{margin-top:36px;padding:24px 0;border-top:1px solid #dce2d4;display:flex;justify-content:space-between;gap:20px;align-items:center;flex-wrap:wrap;font-size:12px}.dl-article-end>span{display:flex;gap:10px;align-items:center;color:#6b7564}.dl-article-end i{color:var(--dl-amber);font-size:20px}.dl-article-end a{color:var(--dl-olive);font-weight:600;text-decoration:none}
.dl-article-related{border-top:1px solid #dce2d4;padding-top:44px;margin-top:56px}.dl-article-related-heading{display:flex;justify-content:space-between;align-items:end;gap:24px;margin-bottom:28px}.dl-article-related-heading h2{font-size:32px;color:var(--dl-forest);letter-spacing:-.8px;margin:0}.dl-article-related-heading>a{font-size:13px;color:var(--dl-olive);text-underline-offset:5px}.dl-article-related-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px}.dl-article-card{background:#fff;border:1px solid #dce2d4;border-radius:14px;overflow:hidden;display:flex;flex-direction:column}.dl-article-card-image{display:grid;place-items:center;background:#e8eddf;aspect-ratio:1.5;color:var(--dl-olive);font-size:38px;overflow:hidden}.dl-article-card-image img{width:100%;height:100%;object-fit:cover;transition:transform .25s}.dl-article-card-image:hover img{transform:scale(1.04)}.dl-article-card>div{padding:24px;display:flex;flex-direction:column;flex:1}.dl-article-card h3{font-size:19px;line-height:1.5;margin:0 0 14px}.dl-article-card h3 a{color:var(--dl-forest);text-decoration:none;overflow-wrap:anywhere}.dl-article-card p{font-size:13px;line-height:1.8;color:#6b7564;margin:0 0 20px;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}.dl-article-read{margin-top:auto;display:flex;justify-content:space-between;font-size:12px;font-weight:700;color:var(--dl-olive);text-decoration:none}
.dl-article-page a:focus-visible{outline:3px solid var(--dl-amber);outline-offset:4px}
@media(max-width:980px){.dl-article-layout{grid-template-columns:minmax(0,1fr) 260px;gap:30px}.dl-article-advice,.dl-article-toc{padding:22px}.dl-article-related-grid{gap:16px}.dl-article-card>div{padding:18px}}
@media(max-width:700px){.dl-article-page{padding-bottom:36px}.dl-article-breadcrumb{padding:18px 0;font-size:11px}.dl-article-heading{margin:18px auto 28px;text-align:left}.dl-article-heading h1{font-size:32px;letter-spacing:-.8px}.dl-article-intro{font-size:14px}.dl-article-meta{justify-content:start;gap:16px;font-size:11px}.dl-article-cover{aspect-ratio:1.4;border-radius:12px}.dl-article-layout{display:flex;flex-direction:column;padding-top:30px;gap:28px}.dl-article-main{width:100%}.dl-article-sidebar{position:static;width:100%;display:contents}.dl-article-toc{order:-1;width:100%}.dl-article-advice{width:100%}.dl-article-content{font-size:15px}.dl-article-content h2{font-size:24px}.dl-article-content h3{font-size:20px}.dl-article-related{margin-top:36px;padding-top:30px}.dl-article-related-grid{grid-template-columns:1fr;gap:20px}.dl-article-related-heading{align-items:start;flex-direction:column;gap:16px}.dl-article-related-heading h2{font-size:27px}}
@media(prefers-reduced-motion:reduce){.dl-article-card-image img{transition:none}}
</style>
